// Check that `langStrings` are specified each for a unique language.
func LangStringsHaveUniqueLanguages[L ourtypes.IAbstractLangString](
	langStrings []L) bool {
	languageSet := make(map[string]struct{})

	for _, langString := range langStrings {
		language := langString.Language()
		_, has := languageSet[language]
		if has {
			return false
		}

		languageSet[language] = struct{}{}
	}

	return true
}

// Check that there are no duplicate [ourtypes.IQualifier.Type]'s in
// the `qualifiers`.
func QualifierTypesAreUnique[Q ourtypes.IQualifier](
	qualifiers []Q) bool {
	typeSet := make(map[string]struct{})
	for _, qualifier := range qualifiers {
		t := qualifier.Type()

		_, has := typeSet[t]
		if has {
			return false
		}
		typeSet[t] = struct{}{}
	}
	return true
}

