func constructMatchesXsDateTime() *regexp.Regexp {
	digit := "[0-9]"
	yearFrag := ourcommon.Concat(
		"-?(([1-9]",
		digit,
		digit,
		digit,
		"+)|(0",
		digit,
		digit,
		digit,
		"))",
	)
	monthFrag := "((0[1-9])|(1[0-2]))"
	dayFrag := ourcommon.Concat(
		"((0[1-9])|([12]",
		digit,
		")|(3[01]))",
	)
	hourFrag := ourcommon.Concat(
		"(([01]",
		digit,
		")|(2[0-3]))",
	)
	minuteFrag := ourcommon.Concat(
		"[0-5]",
		digit,
	)
	secondFrag := ourcommon.Concat(
		"([0-5]",
		digit,
		")(\\.",
		digit,
		"+)?",
	)
	endOfDayFrag := "24:00:00(\\.0+)?"
	timezoneFrag := ourcommon.Concat(
		"(Z|(\\+|-)((0",
		digit,
		"|1[0-3]):",
		minuteFrag,
		"|14:00))",
	)
	dateTimeLexicalRep := ourcommon.Concat(
		yearFrag,
		"-",
		monthFrag,
		"-",
		dayFrag,
		"T((",
		hourFrag,
		":",
		minuteFrag,
		":",
		secondFrag,
		")|",
		endOfDayFrag,
		")",
		timezoneFrag,
		"?",
	)
	pattern := ourcommon.Concat(
		"^",
		dateTimeLexicalRep,
		"$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

var matchesXsDateTimeRe = constructMatchesXsDateTime()

// Check that text conforms to the pattern of an `xs:dateTime`.
//
// See: https://www.w3.org/TR/xmlschema-2/#dateTime
//
//   • `text`: Text to be checked
//   • Return True if the text conforms to the pattern
func MatchesXsDateTime(text string) bool {
	return matchesXsDateTimeRe.MatchString(
		text,
	)
}

// Check that `value` is a valid `xs:dateTime`.
//
// Year 1 BCE is the last leap BCE year.
// See https://www.w3.org/TR/xmlschema-2/#dateTime.
func IsXsDateTime(value string) bool {
	// NOTE (mristin):
  	// We can not use date functions from the standard library as it does not
	// handle years BCE (*e.g.*, `-0003-01-02`).

	if !MatchesXsDateTime(value) {
		return false
	}

	date, _, ok := strings.Cut(value, "T")
	if !ok {
		panic(
			fmt.Sprintf(
				"Expected 'T' in the date-time if it matches the expected regex, " +
				"but got: %s",
				value,
			),
		)
	}
	return IsXsDate(date)
}

func constructMatchesXsDecimal() *regexp.Regexp {
	digit := "[0-9]"
	unsignedNoDecimalPtNumeral := ourcommon.Concat(
		digit,
		"+",
	)
	noDecimalPtNumeral := ourcommon.Concat(
		"(\\+|-)?",
		unsignedNoDecimalPtNumeral,
	)
	fracFrag := ourcommon.Concat(
		digit,
		"+",
	)
	unsignedDecimalPtNumeral := ourcommon.Concat(
		"(",
		unsignedNoDecimalPtNumeral,
		"\\.",
		fracFrag,
		"|\\.",
		fracFrag,
		")",
	)
	decimalPtNumeral := ourcommon.Concat(
		"(\\+|-)?",
		unsignedDecimalPtNumeral,
	)
	decimalLexicalRep := ourcommon.Concat(
		"(",
		decimalPtNumeral,
		"|",
		noDecimalPtNumeral,
		")",
	)
	pattern := ourcommon.Concat(
		"^",
		decimalLexicalRep,
		"$",
	)

	return regexp.MustCompile(
		pattern,
	)
}

