// further verification as well, and return abort `true`. Otherwise,
// abort `false` is returned.
func VerifyReference(
	that ourtypes.IReference,
	onError func(*VerificationError) bool,
) (abort bool) {
	abort = false

	if !(len(that.Keys()) >= 1) {
		abort = onError(
			newVerificationError(
				"Keys must contain at least one item.",),
		)
		if abort {
			return
		}
	}

	if !(
		!(len(that.Keys()) >= 1) ||
		ourcommon.MapContains(
			ourconstants.GloballyIdentifiables,
			ourcommon.At(that.Keys(), 0).Type(),
		)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-121: For References the value of type of " +
				"the first key of keys shall be one of Globally " +
				"Identifiables.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesExternalReference &&
		len(that.Keys()) >= 1) ||
		ourcommon.MapContains(
			ourconstants.GenericGloballyIdentifiables,
			ourcommon.At(that.Keys(), 0).Type(),
		)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-122: For external references the value of " +
				"type of the first key of keys shall be one of Generic " +
				"Globally Identifiables.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesModelReference &&
		len(that.Keys()) >= 1) ||
		ourcommon.MapContains(
			ourconstants.AASIdentifiables,
			ourcommon.At(that.Keys(), 0).Type(),
		)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-123: For model references the value of type " +
				"of the first key of keys shall be one of AAS identifiables.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesExternalReference &&
		len(that.Keys()) >= 1) ||
		(ourcommon.MapContains(
			ourconstants.GenericGloballyIdentifiables,
			ourcommon.At(that.Keys(), -1).Type(),
		) ||
		ourcommon.MapContains(
			ourconstants.GenericFragmentKeys,
			ourcommon.At(that.Keys(), -1).Type(),
		))) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-124: For external references the last key " +
				"of keys shall be either one of Generic Globally " +
				"Identifiables or one of Generic Fragment Keys.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesModelReference &&
		len(that.Keys()) > 1) ||
		ourcommon.AllRange(
			func(i int) bool {
				return ourcommon.MapContains(
						ourconstants.FragmentKeys,
						ourcommon.At(that.Keys(), int64(i)).Type(),
					)
			},
			1,
			len(that.Keys()),
		)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-125: For model references with more than " +
				"one key in keys the value of type of each of the keys " +
				"following the first key of keys shall be one of Fragment " +
				"Keys.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesModelReference &&
		len(that.Keys()) > 1) ||
		ourcommon.AllRange(
			func(i int) bool {
				return !ourcommon.MapContains(
						ourconstants.GenericFragmentKeys,
						ourcommon.At(that.Keys(), int64(i)).Type(),
					)
			},
			0,
			len(that.Keys()) - 1,
		)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-126: For model references with more than " +
				"one key in keys the value of type of the last key in " +
				"the reference key chain may be one of Generic Fragment Keys " +
				"or no key at all shall have a value out of Generic Fragment " +
				"Keys.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesModelReference &&
		len(that.Keys()) > 1 &&
		ourcommon.At(that.Keys(), -1).Type() == ourtypes.KeyTypesFragmentReference) ||
		(ourcommon.At(that.Keys(), -2).Type() == ourtypes.KeyTypesFile ||
		ourcommon.At(that.Keys(), -2).Type() == ourtypes.KeyTypesBlob)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-127: For model references, with more than " +
				"one key in keys a key with type Fragment Reference shall be " +
				"preceded by a key with type File or Blob.",
			),
		)
		if abort {
			return
		}
	}

	if !(
		!(that.Type() == ourtypes.ReferenceTypesModelReference &&
		len(that.Keys()) > 2) ||
		ourcommon.AllRange(
			func(i int) bool {
				return !(ourcommon.At(that.Keys(), int64(i)).Type() == ourtypes.KeyTypesSubmodelElementList) ||
					MatchesXsNonNegativeInteger(
						ourcommon.At(that.Keys(), int64(i + 1)).Value(),
					)
			},
			0,
			len(that.Keys()) - 1,
		)) {
		abort = onError(
			newVerificationError(
				"Constraint AASd-128: For model references, the value of " +
				"a key preceded by a key with type Submodel element list is " +
				"an integer number denoting the position in the array of " +
				"the submodel element list.",
			),
		)
		if abort {
			return
		}
	}

	abort = VerifyReferenceTypes(
		that.Type(),
		func(err *VerificationError) bool {
			err.Path.PrependName(
				&ourreporting.NameSegment{
					Name: "Type",
				},
			)
			return onError(err)
		},
	)
	if abort {
		return
	}

	if that.ReferredSemanticID() != nil {
		abort = Verify(
			that.ReferredSemanticID(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "ReferredSemanticID",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	if that.Keys() == nil {
		abort = onError(
			newVerificationError(
				"Required property not set: Keys",
			),
		)
		if abort {
			return
		}
	} else {
		abort = verifyListOf_IKey(
			that.Keys(),
			func(err *VerificationError) bool {
				err.Path.PrependName(
					&ourreporting.NameSegment{
						Name: "Keys",
					},
				)
				return onError(err)
			},
		)
		if abort {
			return
		}
	}

	return
}

